  const grants = useQuery<{ id: string; email: string }[]>(
    modal === "access" && selected ? `/videos/${selected.id}/grants` : null,
  );
  useEffect(() => {
    if (
      !query.data?.items.some((v) =>
        ["queued", "processing", "uploading"].includes(v.status),
      )
    )
      return;
    let active = true;
    const timer = window.setInterval(() => {
      api<Page<Video>>(`/videos?scope=mine&page=${page}&limit=12`)
