            setStatus("resolved");
            setPage(1);
          }}
        >
          Рассмотренные
        </button>
      </div>
      {error && !selected && <ErrorBox message={error} />}{" "}
      {reports.loading ? (
        <Spinner />
      ) : reports.error ? (
        <ErrorBox message={reports.error} retry={reports.reload} />
      ) : reports.data?.length ? (
        <div className="reports">
          {reports.data.map((r) => (
            <article className="report-card panel" key={r.id}>
              <div className="report-top">
                <span className={`badge ${r.hidden ? "red" : ""}`}>
                  {r.hidden
                    ? "Видео скрыто"
                    : r.visibility === "private"
                      ? "Приватное видео"
                      : "Открытое видео"}
                </span>
                <small>{new Date(r.created_at).toLocaleString("ru-RU")}</small>
              </div>
              <h2>{r.title}</h2>
              <p>{r.reason}</p>
              {r.resolution && (
                <p className="resolution">
                  <CheckCircle2 size={17} />
                  {r.resolution}
