              )}
              <div className="report-actions">
                <Link className="button secondary" to={`/watch/${r.video_id}`}>
                  Открыть видео
                </Link>
                {r.status === "open" ? (
                  <>
                    <button
                      className="button secondary"
                      onClick={() => {
                        setSelected(r);
                        setAction("dismiss");
                        setReason("");
                        setError("");
                      }}
                    >
                      Отклонить жалобу
                    </button>
                    <button
                      className="button destructive"
                      onClick={() => {
                        setSelected(r);
                        setAction("hide");
                        setReason("");
                        setError("");
                      }}
                    >
                      Скрыть видео
                    </button>
                  </>
                ) : (
                  r.hidden && (
                    <button
                      className="button secondary"
                      disabled={busy}
                      onClick={async () => {
                        setBusy(true);
                        try {
                          await send(
                            `/moderation/videos/${r.video_id}/restore`,
                            "POST",
                          );
                          reports.reload();
                        } catch (e) {
                          setError((e as Error).message);
                        } finally {
                          setBusy(false);
                        }
                      }}
                    >
                      Восстановить видео
                    </button>
                  )
                )}
              </div>
              {r.visibility === "private" && (
                <small className="muted">
                  Просмотр приватного видео зависит от разрешения владельца.
                </small>
              )}
            </article>
          ))}
        </div>
      ) : (
        <Empty
          title={
            status === "open" ? "Все жалобы рассмотрены" : "Решений пока нет"
          }
          description={
            status === "open"
              ? "Новые обращения появятся здесь."
              : "История рассмотрения появится после первого решения."
          }
        />
      )}{" "}
      {(page > 1 || reports.data?.length === 30) && (
        <div className="pagination">
          <button
            className="button secondary"
            disabled={page === 1}
            onClick={() => setPage((p) => p - 1)}
          >
            Назад
          </button>
          <span>{page}</span>
          <button
            className="button secondary"
            disabled={(reports.data?.length || 0) < 30}
            onClick={() => setPage((p) => p + 1)}
          >
            Далее
          </button>
        </div>
      )}
      {selected && (
        <Modal
          title={action === "hide" ? "Скрыть видео" : "Отклонить жалобу"}
          onClose={() => setSelected(null)}
        >
          <form
            onSubmit={async (e) => {
              e.preventDefault();
              setBusy(true);
              setError("");
              try {
                await send(
                  `/moderation/reports/${selected.id}/resolve`,
                  "POST",
                  { action, reason },
                );
                setSelected(null);
                reports.reload();
              } catch (e) {
                setError((e as Error).message);
              } finally {
                setBusy(false);
              }
            }}
          >
            <p>{selected.title}</p>
            <label>
              Причина решения
              <textarea
                required
                minLength={5}
                maxLength={500}
                value={reason}
                onChange={(e) => setReason(e.target.value)}
              />
            </label>
            {error && <ErrorBox message={error} />}
            <button
              className={`button ${action === "hide" ? "destructive" : "primary"}`}
              disabled={busy}
            >
              Подтвердить решение
            </button>
          </form>
        </Modal>
      )}
    </section>
  );
}
type AdminUser = {
