#!/usr/bin/env python3
"""Reject incomplete browser acceptance, including codec-related skips."""

import json
import sys
from pathlib import Path


def complete(report):
    stats = report.get("stats", {})
    return (
        not report.get("errors")
        and stats.get("expected", 0) > 0
        and all(stats.get(key) == 0 for key in ("unexpected", "flaky", "skipped"))
    )


if __name__ == "__main__":
    report = json.loads(Path(sys.argv[1]).read_text())
    if not complete(report):
        raise SystemExit("INCOMPLETE: browser failures/skips or no passing tests; inspect report.json")
    print("PASS: all selected browser tests passed without skips or retries")

import unittest

from check_e2e_report import complete


class BrowserAcceptanceTest(unittest.TestCase):
    def test_requires_passing_tests_without_omissions(self):
        stats = dict(expected=2, unexpected=0, flaky=0, skipped=0)
        self.assertTrue(complete({"stats": stats}))
        for field in ("unexpected", "flaky", "skipped"):
            self.assertFalse(complete({"stats": {**stats, field: 1}}))
        self.assertFalse(complete({"stats": {**stats, "expected": 0}}))
        self.assertFalse(complete({"stats": stats, "errors": [{"message": "crash"}]}))
        self.assertFalse(complete({}))


if __name__ == "__main__":
    unittest.main()

